import { atlasesOf, effectNames, idleAtlasOf, portraitOf, urlsOf } from '../strip-urls';
import type { Atlas, FighterArt } from '../types';
import { FELINE_CELLS } from './cells';
import { FELINE_CLIPS } from './clips';
import { FELINE_SHEETS } from './sheets';

/** Strips generated by `npm run sprites` (tools/sprites), one folder per colorway. */
const MAIN = import.meta.glob<string>('./main/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT = import.meta.glob<string>('./alt/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
/** Front effects of the strips that have some (portals, star flashes, orbital rings). */
const MAIN_FX = import.meta.glob<string>('./main/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_FX = import.meta.glob<string>('./alt/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});

const MAIN_ATLASES = import.meta.glob<string>('./main/**/*.json', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_ATLASES = import.meta.glob<string>('./alt/**/*.json', {
  eager: true,
  query: '?url',
  import: 'default',
});
const IDLE_ATLASES = import.meta.glob<Atlas>('./*/idle.json', { eager: true, import: 'default' });

const SHARED = {
  portrait: { x: 26, y: 0, size: 58 },
  sheets: FELINE_SHEETS,
  clips: FELINE_CLIPS,
  cells: FELINE_CELLS,
  ownLight: true,
};

/** Silver-white feline mane & tail, black techwear with cyan triangle LEDs, silver-white portals. */
export const FELINE: FighterArt = {
  key: 'feline',
  urls: urlsOf(MAIN, 'main', FELINE_SHEETS),
  fx: urlsOf(MAIN_FX, 'main/fx', effectNames(FELINE_SHEETS, FELINE_CLIPS)),
  atlases: atlasesOf(MAIN_ATLASES, 'main', FELINE_SHEETS, effectNames(FELINE_SHEETS, FELINE_CLIPS)),
  ...idleAtlasOf(IDLE_ATLASES, 'main', FELINE_CLIPS.idle.sheet),
  ...portraitOf(MAIN, 'main'),
  ...SHARED,
};
/** Shadow-panther mane & tail, ivory techwear with rose-astral portals: player 2 in a mirror match. */
export const FELINE_ALT: FighterArt = {
  key: 'feline-alt',
  urls: urlsOf(ALT, 'alt', FELINE_SHEETS),
  fx: urlsOf(ALT_FX, 'alt/fx', effectNames(FELINE_SHEETS, FELINE_CLIPS)),
  atlases: atlasesOf(ALT_ATLASES, 'alt', FELINE_SHEETS, effectNames(FELINE_SHEETS, FELINE_CLIPS)),
  ...idleAtlasOf(IDLE_ATLASES, 'alt', FELINE_CLIPS.idle.sheet),
  ...portraitOf(ALT, 'alt'),
  ...SHARED,
};
